var TEXTS3=[{"id": "deadsea", "title": "טיול לים המלח", "text": "בחופשה נסענו אל ים המלח. המים שם מלוחים מאוד, ולכן אפשר לצוף עליהם בלי לשחות. אבא קרא עיתון בזמן שצפנו. אחרי הרחצה מרחנו על הגוף בוץ שחור.", "nk": "בַּחֲפִשָּׁה נָסַעְנוּ אֶל יַם הַמֶּלַח. הַמַּיִם שָׁם מְלוּחִים מְאוֹד, וְלָכֵן אֶפְשָׁר לָצוּף עֲלֵיהֶם בְּלִי לִשְׂחוֹת. אַבָּא קָרָא עִתּוֹן בִּזְמַן שֶׁצָּפְנוּ. אַחֲרֵי הָרַחְצָה מָרַחְנוּ עַל הַגּוּף בּוֹץ שָׁחוֹר.", "tr": {"en": "On vacation we went to the Dead Sea. The water there is very salty, so you can float on it without swimming. Dad read a newspaper while we floated. After bathing we smeared black mud on our bodies.", "ru": "На каникулах мы поехали к Мёртвому морю. Вода там очень солёная, поэтому на ней можно лежать, не плавая. Папа читал газету, пока мы плавали на спине. После купания мы намазались чёрной грязью.", "ar": "في العطلة سافرنا إلى البحر الميت. الماء هناك مالح جدًا، لذلك يمكن الطفو عليه دون سباحة. قرأ أبي جريدة بينما كنا نطفو. بعد الاستحمام دهنا أجسامنا بطين أسود."}, "qs": [{"q": "למה אפשר לצוף בים המלח?", "a": "המים מלוחים מאוד", "d": ["המים קרים מאוד", "המים עמוקים מאוד", "יש שם גלים גדולים"]}, {"q": "מה אבא עשה בזמן שצפו?", "a": "קרא עיתון", "d": ["שחה", "אכל גלידה", "ישן"]}, {"q": "מה מרחו על הגוף?", "a": "בוץ שחור", "d": ["קרם לבן", "חול", "שמן"]}, {"q": "על מה הקטע מספר?", "a": "טיול לים המלח", "d": ["טיול לגן החיות", "ארוחת בוקר", "משחק כדורגל"]}]}, {"id": "bees", "title": "הדבורים", "text": "דבורים חיות בכוורת גדולה. בכוורת יש מלכה אחת ועובדות רבות. העובדות יוצאות לחפש צוף בפרחים, ומביאות אותו לכוורת. מהצוף הן מכינות דבש.", "nk": "דְּבוֹרִים חַיּוֹת בְּכַוֶּרֶת גְּדוֹלָה. בַּכַּוֶּרֶת יֵשׁ מַלְכָּה אַחַת וְעוֹבְדוֹת רַבּוֹת. הָעוֹבְדוֹת יוֹצְאוֹת לְחַפֵּשׂ צוּף בַּפְּרָחִים, וּמְבִיאוֹת אוֹתוֹ לַכַּוֶּרֶת. מֵהַצּוּף הֵן מְכִינוֹת דְּבַשׁ.", "tr": {"en": "Bees live in a big hive. In the hive there is one queen and many workers. The workers go out to look for nectar in flowers and bring it to the hive. From the nectar they make honey.", "ru": "Пчёлы живут в большом улье. В улье одна матка и много рабочих пчёл. Рабочие вылетают искать нектар в цветах и приносят его в улей. Из нектара они делают мёд.", "ar": "تعيش النحلات في خلية كبيرة. في الخلية ملكة واحدة وعاملات كثيرات. تخرج العاملات للبحث عن الرحيق في الأزهار وتحضره إلى الخلية. من الرحيق تصنع العسل."}, "qs": [{"q": "כמה מלכות יש בכוורת?", "a": "אחת", "d": ["שתיים", "עשר", "אין מלכה"]}, {"q": "מה העובדות מחפשות בפרחים?", "a": "צוף", "d": ["דבש", "עלים", "מים"]}, {"q": "מה מכינות מהצוף?", "a": "דבש", "d": ["לחם", "חלב", "עוגה"]}, {"q": "על מה הקטע מספר?", "a": "חיי הדבורים בכוורת", "d": ["גינת פרחים", "הכנת עוגה", "בית ספר"]}]}, {"id": "birthday", "title": "יום הולדת לדנה", "text": "דנה חוגגת יום הולדת תשע. היא הזמינה את כל הכיתה לגינה של הבית. הילדים שיחקו בכדורגל ואכלו עוגת שוקולד. בסוף כל ילד קיבל בלון צבעוני.", "nk": "דָּנָה חוֹגֶגֶת יוֹם הֻלֶּדֶת תֵּשַׁע. הִיא הִזְמִינָה אֶת כָּל הַכִּתָּה לַגִּנָּה שֶׁל הַבַּיִת. הַיְלָדִים שִׂחֲקוּ בְּכַדּוּרֶגֶל וְאָכְלוּ עוּגַת שׁוֹקוֹלָד. בַּסּוֹף כָּל יֶלֶד קִבֵּל בָּלוֹן צִבְעוֹנִי.", "tr": {"en": "Dana is celebrating her ninth birthday. She invited the whole class to the garden of her house. The children played football and ate chocolate cake. At the end every child got a colorful balloon.", "ru": "Дана празднует девятый день рождения. Она пригласила весь класс в сад у дома. Дети играли в футбол и ели шоколадный торт. В конце каждый ребёнок получил цветной воздушный шарик.", "ar": "تحتفل دانا بعيد ميلادها التاسع. دعت الصف كله إلى حديقة البيت. لعب الأولاد كرة القدم وأكلوا كعكة شوكولاتة. في النهاية حصل كل ولد على بالون ملون."}, "qs": [{"q": "בת כמה דנה?", "a": "תשע", "d": ["שבע", "שמונה", "עשר"]}, {"q": "איפה הייתה המסיבה?", "a": "בגינה של הבית", "d": ["בכיתה", "בים", "במסעדה"]}, {"q": "מה קיבל כל ילד בסוף?", "a": "בלון צבעוני", "d": ["עוגה", "כדור", "ספר"]}, {"q": "איזה משחק שיחקו?", "a": "כדורגל", "d": ["תופסת", "קלפים", "שחמט"]}]}, {"id": "race", "title": "המרוץ", "text": "פעם ארנב צחק על צב איטי. הצב אמר: בוא נתחרה במרוץ. הארנב רץ מהר, ואז נרדם מתחת לעץ. הצב המשיך ללכת לאט ולא עצר, והגיע ראשון לקו הסיום.", "nk": "פַּעַם אַרְנָב צָחַק עַל צָב אִטִּי. הַצָּב אָמַר: בּוֹא נִתְחָרֶה בְּמֶרוֹץ. הָאַרְנָב רָץ מַהֵר, וְאָז נִרְדַּם מִתַּחַת לְעֵץ. הַצָּב הִמְשִׁיךְ לָלֶכֶת לְאַט וְלֹא עָצַר, וְהִגִּיעַ רִאשׁוֹן לְקַו הַסִּיּוּם.", "tr": {"en": "Once a hare laughed at a slow tortoise. The tortoise said: let's have a race. The hare ran fast, and then fell asleep under a tree. The tortoise kept walking slowly and did not stop, and reached the finish line first.", "ru": "Однажды заяц посмеялся над медленной черепахой. Черепаха сказала: давай устроим гонку. Заяц быстро бежал, а потом уснул под деревом. Черепаха продолжала медленно идти, не останавливаясь, и первой пришла к финишу.", "ar": "ضحك أرنب مرة على سلحفاة بطيئة. قالت السلحفاة: لنتسابق. ركض الأرنب بسرعة ثم نام تحت شجرة. واصلت السلحفاة المشي ببطء دون توقف ووصلت أولًا إلى خط النهاية."}, "qs": [{"q": "מה עשה הארנב באמצע המרוץ?", "a": "נרדם מתחת לעץ", "d": ["אכל גזר", "עצר לשתות", "חזר הביתה"]}, {"q": "מי הגיע ראשון?", "a": "הצב", "d": ["הארנב", "שניהם יחד", "אף אחד"]}, {"q": "מה אפשר ללמוד מהסיפור?", "a": "מי שממשיך ולא עוצר מצליח", "d": ["כדאי לישון הרבה", "ארנבים הם הכי מהירים", "אסור להתחרות"]}]}, {"id": "beach", "title": "ניקיון בחוף", "text": "ילדי הכיתה ניקו את החוף. הם אספו בקבוקים ושקיות לתוך שקים גדולים. המורה הסבירה שזבל פוגע בדגים ובציפורים. כולם הבטיחו לשמור על הניקיון.", "nk": "יַלְדֵי הַכִּתָּה נִקּוּ אֶת הַחוֹף. הֵם אָסְפוּ בַּקְבּוּקִים וְשַׂקִּיּוֹת לְתוֹךְ שַׂקִּים גְּדוֹלִים. הַמּוֹרָה הִסְבִּירָה שֶׁזֶּבֶל פּוֹגֵעַ בַּדָּגִים וּבַצִּפֳּרִים. כֻּלָּם הִבְטִיחוּ לִשְׁמֹר עַל הַנִּקָּיוֹן.", "tr": {"en": "The children of the class cleaned the beach. They collected bottles and bags into big sacks. The teacher explained that trash harms fish and birds. Everyone promised to keep it clean.", "ru": "Дети из класса убрали пляж. Они собрали бутылки и пакеты в большие мешки. Учительница объяснила, что мусор вредит рыбам и птицам. Все пообещали беречь чистоту.", "ar": "نظف أولاد الصف الشاطئ. جمعوا زجاجات وأكياسًا في أكياس كبيرة. شرحت المعلمة أن القمامة تؤذي الأسماك والطيور. وعد الجميع بالحفاظ على النظافة."}, "qs": [{"q": "מה ניקו הילדים?", "a": "את החוף", "d": ["את הכיתה", "את החצר", "את הרחוב"]}, {"q": "למה זבל מזיק?", "a": "הוא פוגע בדגים ובציפורים", "d": ["הוא עושה רעש", "הוא עולה כסף", "הוא נראה יפה"]}, {"q": "מה אספו?", "a": "בקבוקים ושקיות", "d": ["צדפים", "אבנים", "ענפים"]}]}, {"id": "library", "title": "הספרייה", "text": "בספרייה השכונתית יש ספרים לכל הגילים. כדי לשאול ספר צריך כרטיס ספרייה. אפשר לשמור את הספר שלושה שבועות ואז צריך להחזיר אותו. נועם שאל ספר על חלל והחזיר אותו בזמן.", "nk": "בַּסִּפְרִיָּה הַשְּׁכוּנָתִית יֵשׁ סְפָרִים לְכָל הַגִּילִים. כְּדֵי לִשְׁאֹל סֵפֶר צָרִיךְ כַּרְטִיס סִפְרִיָּה. אֶפְשָׁר לִשְׁמֹר אֶת הַסֵּפֶר שְׁלוֹשָׁה שָׁבוּעוֹת וְאָז צָרִיךְ לְהַחֲזִיר אוֹתוֹ. נֹעַם שָׁאַל סֵפֶר עַל חָלָל וְהֶחֱזִיר אוֹתוֹ בַּזְּמַן.", "tr": {"en": "The neighborhood library has books for all ages. To borrow a book you need a library card. You can keep the book for three weeks and then you must return it. Noam borrowed a book about space and returned it on time.", "ru": "В районной библиотеке есть книги для всех возрастов. Чтобы взять книгу, нужен читательский билет. Книгу можно держать три недели, а потом нужно вернуть. Ноам взял книгу о космосе и вернул её вовремя.", "ar": "في مكتبة الحي كتب لكل الأعمار. لاستعارة كتاب يلزم بطاقة مكتبة. يمكن الاحتفاظ بالكتاب ثلاثة أسابيع ثم يجب إعادته. استعار نوعام كتابًا عن الفضاء وأعاده في الوقت."}, "qs": [{"q": "מה צריך כדי לשאול ספר?", "a": "כרטיס ספרייה", "d": ["כסף", "מורה", "תיק"]}, {"q": "כמה זמן אפשר לשמור ספר?", "a": "שלושה שבועות", "d": ["יום אחד", "שבוע אחד", "שנה"]}, {"q": "על מה היה הספר של נועם?", "a": "על חלל", "d": ["על ים", "על כדורגל", "על בישול"]}]}];

